#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int countWordOccurrences(ifstream& file, string word) {
    int count = 0;
    string line;

    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    return count;
}

int main() {
